/**
 * Installing Mossbound as an app.
 *
 * Chrome does not let a page offer to install itself unless a service worker with a `fetch` handler
 * is in charge of it, so the worker (generated by vite.config.ts) is registered first and the offer
 * follows from the event the browser then fires. Until it fires there is nothing to offer: a button
 * that calls an install that the browser has not authorised does nothing at all, so `canInstall`
 * stays false and the title screen shows no button rather than a dead one.
 *
 * iOS has neither the event nor the worker requirement — Safari installs from its own Share menu —
 * so there it stays a sentence telling you where to look (see IS_IOS in screens.ts).
 */
let prompt: { prompt(): Promise<void>; userChoice?: Promise<{ outcome: string }> } | null = null;
let onChange: (() => void) | null = null;

/** Is the browser willing to install this right now? */
export const canInstall = () => prompt !== null;

/** Called when that answer changes, so whatever is on screen can show or drop its button. */
export function onInstallable(f: () => void) {
  onChange = f;
}

/**
 * Ask the browser to install. Resolves true if it went ahead — the event is single-use, so a
 * dismissed prompt is dropped and the button goes away until the browser offers again.
 */
export async function install(): Promise<boolean> {
  const p = prompt;
  if (!p) return false;
  prompt = null;
  onChange?.();
  try {
    await p.prompt();
    const choice = await p.userChoice;
    return choice?.outcome === 'accepted';
  } catch {
    return false;
  }
}

export function watchInstall() {
  if (typeof window === 'undefined') return;
  window.addEventListener('beforeinstallprompt', (e) => {
    // holding onto it is the whole point: unprevented, the browser shows its own bar instead and
    // the page never gets to ask at a moment that suits a game
    e.preventDefault();
    prompt = e as unknown as { prompt(): Promise<void> };
    onChange?.();
  });
  window.addEventListener('appinstalled', () => {
    prompt = null;
    onChange?.();
  });
}

/**
 * Register the worker. Production only: in dev it would serve the e2e suite and `npm run dev` a
 * cached copy of whatever was built last, and every change would arrive one reload late or not at
 * all. A failure here is not worth a word to the player — they lose offline play and the install
 * button, and the game is otherwise exactly as it was.
 */
export function registerWorker() {
  if (!import.meta.env.PROD || typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return;
  const go = () => void navigator.serviceWorker.register(new URL('sw.js', document.baseURI).href, { scope: './' }).catch(() => undefined);
  // Boot is async, so by the time this is called `load` has usually already fired — and a listener
  // added after an event has fired is never called, which is exactly how this registered nothing at
  // all the first time round. Ask what the document is doing rather than assuming it is still loading.
  if (document.readyState === 'complete') go();
  else window.addEventListener('load', go, { once: true });
}
